  .timeline {
    display: flex;
    flex-direction: column;
  }

  /* The rail column of the design, then the content. */
  .job {
    display: grid;
    grid-template-columns: 44px minmax(0, 1fr);
    gap: clamp(12px, 3vw, 32px);
  }

  .rail {
    position: relative;
    display: flex;
    justify-content: center;
  }

  /* One 1px line per item, spanning its full height: stacked, they read as a single
     rail running down the whole timeline. */
  .rail::before {
    content: '';
    position: absolute;
    inset-block: 0;
    width: 1px;
    background: var(--color-line);
  }

  .dot {
    position: relative;
    margin-top: 28px;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--color-bg);
    border: 2px solid var(--color-line);
    /* The ring in the page color is what hides the rail behind the dot. */
    box-shadow: 0 0 0 4px var(--color-bg);
  }

  .dot.current {
    border-color: var(--color-accent);
    box-shadow:
      0 0 0 4px var(--color-bg),
      0 0 16px var(--color-accent);
  }

  /* Borderless at rest like the mock; the card of `DESIGN_SPEC` §4 materializes on
     hover. The bottom margin is inside the grid row, so the rail keeps spanning it. */
  .card {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));
    gap: 20px;
    align-items: start;
    min-width: 0;
    padding: 20px;
    margin-bottom: 16px;
    border: 1px solid transparent;
    border-radius: 20px;
    transition:
      border-color 0.25s,
      background 0.25s,
      box-shadow 0.25s;
  }

  .card:hover {
    background: var(--color-surface);
    border-color: color-mix(in srgb, var(--color-accent) 45%, transparent);
    box-shadow: 0 20px 60px var(--color-shadow-card);
  }

  /* The 4px lift of `DESIGN_SPEC` §4 is motion: with `reduce` the card still materializes
     on hover, it just stays where it is. */
  @media (prefers-reduced-motion: no-preference) {
    .card {
      transition:
        transform 0.25s,
        border-color 0.25s,
        background 0.25s,
        box-shadow 0.25s;
    }

    .card:hover {
      transform: translateY(-4px);
    }
  }

  .who {
    display: flex;
    gap: 16px;
    align-items: center;
    min-width: 0;
  }

  .logo {
    flex: none;
    display: grid;
    place-items: center;
    width: 56px;
    height: 56px;
    border-radius: 16px;
    border: 1px solid var(--color-line);
    font-size: 11px;
    letter-spacing: 0.06em;
