Base.astro  5.2K

/* ── Layout utilities ────────────────────────────────────────────────────────
   The spacing of `DESIGN_SPEC §2`, so no component repeats the magic numbers.
   The hero padding is deliberately not here: it appears exactly once. */

@utility container-page {
  max-width: 1200px;
  margin-inline: auto;
  padding-inline: clamp(20px, 4vw, 48px);
}

@utility section-y {
  padding-block: clamp(56px, 7vw, 100px);
}

@utility section-divider {
  border-top: 1px solid var(--color-line);
}

/* ── Skip link ────────────────────────────────────────────────────────────────
   The one thing here that is not in the design (`spec 16` §4): with a sticky nav and
   eight sections, tabbing past the nav on every page load is exactly what a skip link
   exists for. Styled here rather than in `Base.astro`, which owns no styles of its own.

   Off the top of the viewport until it takes focus, and moved with `top` rather than a
   transform so nothing animates for a visitor who asked for no motion. */

@layer components {
  .skip-link {
    position: fixed;
    top: -100px;
    left: 12px;
    z-index: 30;
    padding: 10px 18px;
    border: 1px solid var(--color-accent);
    border-radius: 999px;
    background: var(--color-bg);
    color: var(--color-ink);
    font-size: 15px;
    font-weight: 500;
  }

  .skip-link:focus-visible {
    top: 12px;
  }
}

/* ── Aurora ───────────────────────────────────────────────────────────────────
   The site's background layer (`MOTION_SPEC §4`): three blurred blobs, fixed, the
   only thing painted at z-index 0. Decoration — `aria-hidden` in the markup, no
   pointer events, and readable without JS since it needs none to show. */

@layer components {
  .aurora {
    position: fixed;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    pointer-events: none;
    /* Scroll drives filter/opacity/transform once per frame; this smooths the steps. */
    transition:
      filter 0.2s linear,
      opacity 0.2s linear;
  }

  .aurora > * {
    position: absolute;
    border-radius: 50%;
  }

  .aurora > :nth-child(1) {
    left: 55%;
    top: -10%;
    width: 56vw;
    height: 56vw;
    filter: blur(90px);
    background: light-dark(
      color-mix(in srgb, var(--color-accent) 22%, transparent),
      color-mix(in srgb, var(--color-accent) 16%, transparent)
    );
  }

  .aurora > :nth-child(2) {
    left: 20%;
    top: 30%;
    width: 44vw;
    height: 44vw;
    filter: blur(100px);
    background: color-mix(in srgb, var(--color-violet) 14%, transparent);
  }

  .aurora > :nth-child(3) {
    left: 70%;
    top: 40%;
    width: 36vw;
    height: 36vw;
    filter: blur(90px);
    background: light-dark(
      color-mix(in srgb, var(--color-accent) 12%, transparent),
      color-mix(in srgb, var(--color-accent) 8%, transparent)
    );
  }

  /* Two blobs on narrow viewports (`MOTION_SPEC §13`). */
  @media (width < 720px) {
    .aurora > :nth-child(3) {
      display: none;
    }
  }

  @media (prefers-reduced-motion: no-preference) {
    .aurora > :nth-child(1) {
      animation: aur1 16s ease-in-out infinite alternate;
    }

    .aurora > :nth-child(2) {
      animation: aur2 20s ease-in-out infinite alternate;
    }

    .aurora > :nth-child(3) {
      animation: aur1 24s ease-in-out infinite alternate-reverse;
    }

    /* Resting opacity of the scroll ramp. Only with JS, which raises it on the first
       frame — without JS the aurora stays at full strength instead of dimmed. */
    .has-js .aurora {
      opacity: 0.45;
    }
  }
}

/* ── Node network ─────────────────────────────────────────────────────────────
   The hero's canvas (`MOTION_SPEC §3`). Created by `motion/network.ts` and never
   server-rendered, so it exists neither without JS nor with reduced motion —
   which is also why its rule lives here instead of in a scoped component style.

   `color` and `border-color` are how the canvas learns the theme: `network.ts`
   reads them back resolved from `getComputedStyle`, so it repaints in the right
   accent when the toggle flips, and never names a color of its own. */

@layer components {
  .hero-net {
    position: absolute;
    inset: 0;
    z-index: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    color: var(--color-accent);
    border-color: var(--color-violet);
    mask-image: linear-gradient(180deg, #000 55%, transparent);
  }
}

