import { chromium } from 'playwright'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1512, height: 950 }, deviceScaleFactor: 2 })
await page.goto('http://localhost:4321/', { waitUntil: 'networkidle' })
await page.waitForTimeout(2500)

const report = await page.evaluate(() => {
  const out: Record<string, unknown> = {}
  const de = document.documentElement
  out.viewport = { inner: innerWidth, client: de.clientWidth, scrollW: de.scrollWidth }

  // 1. horizontal overflow offenders
  const offenders: string[] = []
  for (const el of document.querySelectorAll<HTMLElement>('*')) {
    const r = el.getBoundingClientRect()
    if (r.width === 0) continue
    if (r.right > de.clientWidth + 1 || r.left < -1) {
      offenders.push(`${el.tagName.toLowerCase()}.${el.className.toString().slice(0, 40)} L=${Math.round(r.left)} R=${Math.round(r.right)} W=${Math.round(r.width)}`)
    }
  }
  out.overflowX = offenders.slice(0, 25)

  // 2. nav vs container alignment
  const navBrand = document.querySelector('.brand')!.getBoundingClientRect()
  const nav = document.querySelector('nav.nav')!.getBoundingClientRect()
  const cont = document.querySelector('#stack .container-page')!.getBoundingClientRect()
  out.alignment = { navLeft: navBrand.left, navRight: nav.right, containerLeft: cont.left, containerRight: cont.right }

  // 3. lang toggle geometry
  const lang = document.querySelector<HTMLElement>('.toggle.lang')!
  const lr = lang.getBoundingClientRect()
  out.langToggle = { w: Math.round(lr.width), h: Math.round(lr.height), scrollH: lang.scrollHeight, text: lang.textContent?.trim(), lineHeight: getComputedStyle(lang).lineHeight, whiteSpace: getComputedStyle(lang).whiteSpace }

  // 4. timeline dot vs logo center
  out.timeline = [...document.querySelectorAll('.job')].map((job) => {
    const dot = job.querySelector('.dot')!.getBoundingClientRect()
    const logo = job.querySelector('.logo')!.getBoundingClientRect()
    const card = job.querySelector('.card')!.getBoundingClientRect()
    return { company: job.querySelector('.company')?.textContent?.trim(), dotCenter: Math.round(dot.top + dot.height / 2 - card.top), logoCenter: Math.round(logo.top + logo.height / 2 - card.top) }
  })

  // 5. also-list direction
  const also = document.querySelector<HTMLElement>('.also-list')!
  out.alsoList = { display: getComputedStyle(also).display, h: Math.round(also.getBoundingClientRect().height), items: also.children.length }

  // 6. stack rows
  out.stack = [...document.querySelectorAll('#stack .row')].map((row) => {
    const track = row.querySelector<HTMLElement>('.track')!
    return { rowW: Math.round(row.getBoundingClientRect().width), trackW: Math.round(track.getBoundingClientRect().width), chips: track.querySelectorAll('.chip').length / 2, mask: getComputedStyle(row).maskImage.slice(0, 60), overflow: getComputedStyle(row as HTMLElement).overflow }
  })
  const sub = document.querySelector<HTMLElement>('#stack header > p.text-body')!
  out.stackSub = { rect: sub.getBoundingClientRect().toJSON(), text: sub.textContent?.slice(0, 30) }

  // 7. hero geometry
  const h1 = document.querySelector('.hero h1')!.getBoundingClientRect()
  const consoleCard = document.querySelector('.hero .console, .hero [class*="console"]')?.getBoundingClientRect()
  const cols = document.querySelector('.hero .columns')!.getBoundingClientRect()
  out.hero = { h1: { w: Math.round(h1.width), h: Math.round(h1.height), fontSize: getComputedStyle(document.querySelector('.hero h1')!).fontSize, lineHeight: getComputedStyle(document.querySelector('.hero h1')!).lineHeight }, console: consoleCard ? { w: Math.round(consoleCard.width), h: Math.round(consoleCard.height) } : null, columns: { w: Math.round(cols.width), h: Math.round(cols.height) } }

  return out
})

console.log(JSON.stringify(report, null, 2))
await browser.close()
