input.new_string:
/* `content-box` is the whole of issue 19. `DESIGN_SPEC` §2 reads
   `max-width: 1200px; padding: 0 clamp(20px, 4vw, 48px)`, which is ambiguous, and the
   reset's `border-box` resolves it the wrong way: the cap swallows the gutter and the
   grid comes out 1104px. The mock's own container is `content-box` — 1200 of content
   inside a 1296 border box — so the 1200 is the *content*, and the padding is the margin
   the page keeps from the viewport edge. Only viewports past 1296px see any difference:
   below the cap, `width: auto` has always made the content box the parent minus the
   padding, whatever `box-sizing` says. */
@utility container-page {
  box-sizing: content-box;
  max-width: 1200px;
  margin-inline: auto;
  padding-inline: clamp(20px, 4vw, 48px);
}

