input.new_string:
@utility container-page {
  /* Named, because a flex or grid item cannot inherit block layout's `width: auto` and
     has to restate it — see `.inner` in `Method.astro`, the one place that needs them. */
  --container-max: 1200px;
  --container-pad: clamp(20px, 4vw, 48px);
  box-sizing: content-box;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-pad);
}

/* The only `container-page` in the site that is a flex item, and auto inline margins
   beat `align-items: stretch`: the box shrinks to fit its content — 1124px — instead of
   taking the 1200 every other section gets. So block layout's `width: auto` (the parent
   minus the gutters, capped by the grid) is restated here, which is the one thing a
   flex item cannot inherit. `.pin` pads only on the block axis, so `100%` is the full
   width of the track. */
.inner {
  display: flex;
  flex-direction: column;
  gap: 40px;
  width: min(100% - 2 * var(--container-pad), var(--container-max));
}

