input.new_string:
// The static build, served exactly as it ships. 4321 is `astro preview`'s own default and
// stays the default here; `PORT` exists because several worktrees run this suite at once.
// Without it they all share one port, and `reuseExistingServer` would quietly hand every
// run the *first* worktree's `dist/` — a suite that passes against someone else's build.
const PORT = Number(process.env.PORT) || 4321
const baseURL = `http://localhost:${PORT}`

// `strictPort`: `astro preview` otherwise walks forward to the next free port, which is
// silent and fine for a human and wrong for Playwright — it waits on the port it asked
// for and times out after 60s with nothing to read. Erroring on a busy port is what
// makes several worktrees able to run the suite at the same time.
vite: {
  plugins: [tailwindcss()],
  json: { stringify: false },
  preview: { strictPort: true },
},

